create table deputy_import_batches(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),filename text not null,source_type text not null check(source_type in('CSV','XLSX')),source_timezone text not null,target_timezone text not null default'Australia/Brisbane',content_hash text not null,imported_at timestamptz not null default now(),covered_from date,covered_to date,raw_rows integer not null default 0,approved_rows integer not null default 0,provisional_rows integer not null default 0,quarantined_rows integer not null default 0,status text not null check(status in('PROCESSING','COMPLETED','FAILED')),imported_by uuid,imported_by_email text,error_message text,unique(organization_id,content_hash));
create table deputy_raw_timesheets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),import_batch_id uuid not null references deputy_import_batches(id),source_row_key text not null,source_timesheet_id text,employee_id text,person_key text,display_name text,timesheet_date date,raw_area text,normalized_area text,start_at timestamptz,end_at timestamptz,total_hours numeric,meal_break_hours numeric,approval_status text not null check(approval_status in('APPROVED','PROVISIONAL','INCOMPLETE')),row_status text not null check(row_status in('ACCEPTED','QUARANTINED')),quarantine_reasons text[] not null default'{}',raw_data jsonb not null,created_at timestamptz not null default now(),unique(import_batch_id,source_row_key));
create table deputy_area_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),raw_area text not null,normalized_area text not null,active boolean not null default true,unique(organization_id,raw_area));create index deputy_batch_date_idx on deputy_import_batches(organization_id,imported_at desc);create index deputy_period_idx on deputy_raw_timesheets(organization_id,timesheet_date,normalized_area);create index deputy_quarantine_idx on deputy_raw_timesheets(organization_id,row_status)where row_status='QUARANTINED';
insert into deputy_area_mappings(organization_id,raw_area,normalized_area)select o.id,m.r,m.n from organizations o cross join(values('DTG','DTG_OPERATOR'),('Underprint','UP_OPERATOR'),('Screen Printing','SCREEN_PRINT_CREW'),('ScreenPrinting','SCREEN_PRINT_CREW'),('DTG Tunnel','SHARED_DISPATCH'),('UP Tunnel','SHARED_DISPATCH'),('Floater','SHARED_DISPATCH'),('Screen Room','SCREEN_ROOM'),('Project','INDIRECT'),('P/H Not worked','NON_WORKED'),('PH Not worked','NON_WORKED'))m(r,n)on conflict do nothing;alter table deputy_import_batches enable row level security;alter table deputy_raw_timesheets enable row level security;alter table deputy_area_mappings enable row level security;revoke all on deputy_import_batches,deputy_raw_timesheets,deputy_area_mappings from anon,authenticated;grant select,insert,update on deputy_import_batches,deputy_raw_timesheets to service_role;grant select,insert,update,delete on deputy_area_mappings to service_role;
